1	// Starfall Bulwark — main loop, wave director, economy, events, blessing
2	// drafts, site protocol bridge, G debug hooks and the ?autotest=1 suite.
3	import * as THREE from '../vendor/three.module.min.js';
4	import { makeWorld } from './world.js';
5	import { makeFX } from './fx.js';
6	import { makeEnemy, ENEMY, AFFIX } from './enemies.js';
7	import { TOWERS, makeTower, bindCurve, sellValue } from './towers.js';
8	import { makeAudio } from './audio.js';
9	import { makeUI } from './ui.js';
10	import { keys, pressed, mouse, endFrame, debugPanel, initTouch } from './input.js';
11	import { glowTex } from './assets.js';
12	
13	const DT = 1 / 60, CORE_MAX = 20, START_ESS = 130, TOTAL_WAVES = 10;
14	const SPAWN_IV = { crawler: 1.0, runner: .7, wisp: 1.2, brute: 1.6, shaman: 1.8, colossus: 3 };
15	
16	const WAVES = [
17	  [['crawler', 6]],
18	  [['crawler', 8], ['runner', 3]],
19	  [['crawler', 6], ['runner', 4], ['brute', 1]],
20	  [['crawler', 10], ['wisp', 5]],
21	  [['runner', 6], ['brute', 3], ['shaman', 1]],
22	  [['crawler', 8], ['wisp', 6], ['shaman', 2]],
23	  [['runner', 12], ['brute', 4]],
24	  [['crawler', 8], ['runner', 6], ['brute', 3], ['shaman', 2]],
25	  [['wisp', 10], ['shaman', 4], ['brute', 3]],
26	  [['colossus', 1], ['crawler', 8]],
27	];
28	
29	const BLESSINGS = [
30	  { id: 'sharp', zh: '锋鸣', glyph: '➶', max: 4, desc: '弩箭塔伤害 +20%', apply: () => mods.ballistaDmg += .2 },
31	  { id: 'alloy', zh: '磐晶合金', glyph: '◈', max: 4, desc: '全塔伤害 +8%', apply: () => mods.allDmg += .08 },
32	  { id: 'lens', zh: '透镜阵列', glyph: '◎', max: 3, desc: '全塔射程 +10%', apply: () => mods.range += .1 },
33	  { id: 'chill', zh: '霜寒入髓', glyph: '❄', max: 3, desc: '减速效果 +12%', apply: () => mods.slow += .12 },
34	  { id: 'grid', zh: '导电晶格', glyph: '⚡', max: 2, desc: '连雷弹跳 +1', apply: () => mods.chain += 1 },
35	  { id: 'ember', zh: '燃熔余烬', glyph: '☀', max: 2, desc: '迫炮溅射 +20%', apply: () => mods.splash += .2 },
36	  { id: 'focus', zh: '聚星光焦', glyph: '✧', max: 3, desc: '棱镜光束伤害 +25%', apply: () => mods.prismDmg += .25 },
37	  { id: 'well', zh: '潮汐聚灵', glyph: '◍', max: 4, desc: '星尘获取 +15%', apply: () => mods.essence += .15 },
38	  { id: 'weave', zh: '核心重塑', glyph: '❖', max: 99, desc: '立刻修复星核 +4', apply: () => { coreHp = Math.min(CORE_MAX, coreHp + 4); world.setCoreFrac(coreHp / CORE_MAX); } },
39	  { id: 'cap', zh: '过载电容', glyph: '⟡', max: 4, desc: '全塔射速 +8%', apply: () => mods.rate += .08 },
40	];
41	
42	const EVENTS = {
43	  tide:    { zh: '精 华 潮', sub: '本波击杀星尘翻倍', deep: false, apply: () => rewardMult = 2, revert: () => rewardMult = 1 },
44	  meteor:  { zh: '星 陨', sub: '陨石将坠入战场', deep: false, apply: () => { meteorQ = [3, 7, 11]; }, revert: () => meteorQ = [] },
45	  fog:     { zh: '迷 雾', sub: '本波全塔射程 -20%', deep: false, apply: () => fogWave = true, revert: () => fogWave = false },
46	  over:    { zh: '超 频', sub: '开波 18 秒射速 +45%', deep: false, apply: () => overchargeT = 18, revert: () => overchargeT = 0 },
47	  swarm:   { zh: '虫 潮', sub: '本波敌群 +30%', deep: false, apply: () => swarmMult = 1.3, revert: () => swarmMult = 1 },
48	  emp:     { zh: '磁 暴', sub: '随机哨塔将三次停机 4 秒', deep: true, apply: () => { empQ = [2, 10, 18]; }, revert: () => empQ = [] },
49	  corrode: { zh: '晶 蚀', sub: '本波敌群护甲 +3', deep: true, apply: () => waveArmor += 3, revert: () => waveArmor -= 3 },
50	  frenzy:  { zh: '狂 潮', sub: '本波敌群移速 +30%', deep: true, apply: () => waveSpd += .3, revert: () => waveSpd -= .3 },
51	};
52	
53	// --- state ---
54	let mode = 'title';                 // title | build | combat | draft | over | win
55	let wave = 0, wavesCleared = 0, endless = false;
56	let essence = START_ESS, coreHp = CORE_MAX;
57	let towers = [], enemies = [], spawnQ = [], meteorQ = [];
58	let speed = 1, paused = false, callT = 0, combatT = 0, overchargeT = 0;
59	let rewardMult = 1, fogWave = false, swarmMult = 1, lastEvent = '';
60	let waveArmor = 0, waveSpd = 0, empQ = [];
61	let qCd = 0, eCd = 0, rCd = 0, lastCycle = 0;
62	let noAuto = false;                 // autotest guard: build countdown never auto-calls
63	let selPad = -1, selTower = null;
64	let best = 0, newBest = false, nanFlag = false;
65	let mods, counts, reportTarget = null;
66	let reports = [];
67	const G = { err: [] }; window.__G = G;
68	
69	try { best = parseInt(localStorage.getItem('sfb.best') || '0') || 0; } catch (e) { best = 0; }
70	function saveBest() {
71	  const w = endless ? wave : Math.max(wavesCleared, wave);
72	  if (w > best) { best = w; newBest = true; try { localStorage.setItem('sfb.best', String(best)); } catch (e) { } }
73	}
74	
75	function resetState(toEndless = false) {
76	  wave = toEndless ? TOTAL_WAVES : 0;
77	  endless = toEndless; wavesCleared = 0;
78	  essence = START_ESS; coreHp = CORE_MAX;
79	  towers.forEach(t => t.dispose(world.scene)); towers = [];
80	  enemies.forEach(e => e.dispose(world.scene)); enemies = [];
81	  spawnQ = []; meteorQ = []; empQ = []; starfallQ = [];
82	  speed = 1; paused = false; callT = 0; combatT = 0; overchargeT = 0;
83	  rewardMult = 1; fogWave = false; swarmMult = 1; lastEvent = '';
84	  waveArmor = 0; waveSpd = 0; qCd = 0; eCd = 0; rCd = 0; lastCycle = 0;
85	  selPad = -1; selTower = null; newBest = false; nanFlag = false;
86	  mods = { ballistaDmg: 1, allDmg: 1, range: 1, rate: 1, slow: 0, chain: 0, splash: 1, prismDmg: 1, essence: 1 };
87	  counts = {};
88	  world.pads.forEach(p => { p.tower = null; p.glow.material.opacity = 0; });
89	  fx.clear(); ui.hideDraft(); ui.hideEnd(); ui.towerPanel(null); ui.boss(null);
90	  ui.speed(1); ui.pause(false); ui.callBtn(false); world.setCoreFrac(1);
91	}
92	
93	// --- boot ---
94	const world = makeWorld(document.getElementById('gl'));
95	bindCurve(world);
96	const fx = makeFX(world.scene);
97	const glowT = glowTex();
98	const audio = makeAudio();
99	const ui = makeUI({
100	  onSpeed: toggleSpeed, onPause: togglePause, onMute: () => ui.mute(audio.toggleMute()),
101	  onCall: () => callWave(true), onUpgrade: upgradeSel, onSell: sellSel, onDeselect: deselect,
102	  onBuild: (key) => buildOn(key), onStart: () => startGame(false),
103	  onSkill: (key) => { if (key === 'Q') castStarfall(); else if (key === 'E') castNova(); else if (key === 'R') castOverload(); },
104	});
105	
106	// --- protocol (site bridge) ---
107	function report(kind, payload = {}) {
108	  const frame = { kind, ...payload };
109	  reports.push(frame);
110	  try {
111	    if (reportTarget) reportTarget(frame);
112	    else if (window.parent !== window) window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: frame }, '*');
113	  } catch (e) { }
114	}
115	G.setReportTarget = (fn) => { reportTarget = fn; };
116	report('ready', { game: 'starfall-bulwark' });
117	
118	// --- waves / director ---
119	function waveComp(w) {
120	  if (!endless && w <= TOTAL_WAVES) return WAVES[w - 1] || WAVES[0];
121	  const idx = Math.max(0, w - TOTAL_WAVES - 1);
122	  const base = WAVES[idx % 10].map(x => [...x]);
123	  const comp = base.filter(g => g[0] !== 'colossus');
124	  if (idx % 5 === 4) comp.unshift(['colossus', 1 + Math.floor(idx / 10)]);   // +1 colossus per 2 cycles
125	  return comp;
126	}
127	function wavePlan(w) {
128	  const idx = Math.max(0, w - TOTAL_WAVES - 1);
129	  const cycle = Math.floor(idx / 5) + 1;
130	  // compound +10% per deep wave — maxed towers alone cannot keep up, actives required
131	  return { hpMult: Math.pow(1.10, idx) * (1 + .16 * cycle), spdMult: 1 + Math.min(.06 * (cycle - 1), .5), cycle, armorAdd: Math.floor(idx / 8) };
132	}
133	function buildSpawnQ(comp, t0 = 1) {
134	  const q = [];
135	  let gi = 0;
136	  for (const [kind, count0] of comp) {
137	    const count = Math.max(1, Math.round(count0 * swarmMult));
138	    for (let i = 0; i < count; i++) q.push({ kind, t: t0 + gi * .55 + i * SPAWN_IV[kind] });
139	    gi++;
140	  }
141	  q.sort((a, b) => a.t - b.t);
142	  return q;
143	}
144	function nextWaveText(w) {
145	  return waveComp(w).map(([k, n]) => `${ENEMY[k].zh}×${n}`).join('  ');
146	}
147	function callWave(bonus = true) {
148	  if (mode !== 'build') return false;
149	  if (bonus && callT > 0) gain(15);
150	  wave++;
151	  mode = 'combat'; combatT = 0;
152	  swarmMult = 1; rewardMult = 1; fogWave = false; overchargeT = 0;
153	  const comp = waveComp(wave);
154	  const bossWave = comp.some(g => g[0] === 'colossus');
155	  const plan = wavePlan(wave);
156	  // random event roll first (swarm must affect this wave's spawn queue);
157	  // deep waves add hostile events and the roll chance climbs per cycle
158	  if (!bossWave && Math.random() < (endless ? Math.min(.55 + .04 * plan.cycle, .8) : .4)) {
159	    const pool = Object.keys(EVENTS).filter(k => k !== lastEvent && (!EVENTS[k].deep || (endless && wave >= TOTAL_WAVES + 5)));
160	    const ev = pool[(Math.random() * pool.length) | 0];
161	    lastEvent = ev;
162	    EVENTS[ev].apply();
163	    ui.banner(EVENTS[ev].zh, EVENTS[ev].sub, 2.6);
164	  }
165	  // deep-tide cycle announcement
166	  if (endless && plan.cycle > lastCycle) {
167	    lastCycle = plan.cycle;
168	    const news = plan.cycle === 2 ? '新词缀「裂」：死亡分裂' : plan.cycle === 3 ? '新词缀「盾」：再生护盾' : plan.cycle === 4 ? '新词缀「潜」：周期潜地' : '敌群变异加剧';
169	    setTimeout(() => { ui.banner(`深 潮 循 环 ${plan.cycle}`, news, 2.4); }, 2600);
170	  }
171	  spawnQ = buildSpawnQ(comp);
172	  audio.setState(bossWave ? 'boss' : 'combat');
173	  ui.banner(bossWave ? `裂 地 巨 像${comp[0][1] > 1 ? ' ×' + comp[0][1] : ''}` : `第 ${wave} 波`, bossWave ? '踏碎大地的轰鸣' : '来袭');
174	  audio.play(bossWave ? 'roar' : 'waveStart');
175	  ui.callBtn(false);
176	  return true;
177	}
178	function gain(n) {
179	  const g = Math.floor(n * mods.essence);
180	  essence += g; ui.essencePop(g); audio.play('coin');
181	}
182	function endWave() {
183	  wavesCleared = wave;
184	  saveBest();
185	  gain(20 + 2 * wave);
186	  if (lastEvent && EVENTS[lastEvent]) { EVENTS[lastEvent].revert(); lastEvent = ''; }
187	  fx.clear();                     // in-flight starfall/ projectiles must not bleed into the next wave
188	  starfallQ = [];
189	  audio.setState('build');
190	  report('progress', { wave, score: wavesCleared });
191	  if (!endless && wave >= TOTAL_WAVES) { winGame(); return; }
192	  if (wave % 3 === 0) { startDraft(); return; }
193	  mode = 'build'; callT = 10; ui.callBtn(true, true, callT);
194	  ui.toast(`清波奖励 +${20 + 2 * wave}✦`);
195	}
196	function winGame() {
197	  mode = 'win'; audio.play('victory'); audio.setState('build');
198	  report('complete', { score: wavesCleared });
199	  ui.end({ win: true, waves: wave, best, newBest }, { endless: () => startGame(true), restart: () => startGame(false) });
200	}
201	function loseGame() {
202	  mode = 'over'; audio.play('defeat');
203	  saveBest();
204	  report('gameOver', { score: wavesCleared, progress: wave });
205	  ui.end({ win: false, waves: wave, best, newBest }, { restart: () => startGame(false) });
206	  ui.boss(null);
207	}
208	function startGame(toEndless) {
209	  resetState(toEndless);
210	  ui.hideTitle();
211	  audio.unlock(); audio.setState('build');
212	  mode = 'build'; callT = toEndless ? 8 : 18;
213	  ui.callBtn(true, true, callT);
214	  ui.banner(toEndless ? '无 尽 坚 守' : '坠 星 坚 守', toEndless ? '每 5 波一位巨像' : '点石台建塔 · 提前召唤得星尘', 2.6);
215	}
216	function startDraft() {
217	  mode = 'draft';
218	  const pool = BLESSINGS.filter(b => (counts[b.id] || 0) < b.max);
219	  const cards = []; const cand = [...pool];
220	  while (cards.length < 3 && cand.length) cards.push(cand.splice((Math.random() * cand.length) | 0, 1)[0]);
221	  if (!cards.length) { mode = 'build'; callT = 10; ui.callBtn(true, true, callT); return; }
222	  ui.draft(cards, (i) => {
223	    const b = cards[i];
224	    counts[b.id] = (counts[b.id] || 0) + 1;
225	    b.apply(); audio.play('upgrade');
226	    ui.toast(`获得祝福：${b.zh} — ${b.desc}`);
227	    mode = 'build'; callT = 10; ui.callBtn(true, true, callT);
228	  });
229	}
230	
231	// --- spawning ---
232	function rollAffixes(kind) {
233	  if (!endless) return null;
234	  const { cycle } = wavePlan(wave);
235	  if (Math.random() >= Math.min(.25 + .08 * cycle, .8)) return null;
236	  const fly = ENEMY[kind] && ENEMY[kind].fly;
237	  const base = ['swift', 'vital', 'ward'];
238	  const pool = cycle >= 4 ? [...base, 'split', 'shield', 'burrow']
239	    : cycle === 3 ? [...base, 'split', 'shield']
240	    : cycle === 2 ? [...base, 'split'] : base;
241	  const usable = pool.filter(k => !(fly && !AFFIX[k].fly));
242	  const maxN = Math.min(1 + Math.floor(cycle / 2), 3);   // c1:1 c2:2 c3:2 c4:3 c5:3
243	  const n = Math.min(maxN, usable.length);
244	  const out = [];
245	  let guard = 0;
246	  while (out.length < n && guard++ < 30) {
247	    const k = usable[(Math.random() * usable.length) | 0];
248	    if (!out.includes(k)) out.push(k);
249	  }
250	  return out.length ? out : null;
251	}
252	function spawn(kind, t = 0, opts = {}) {
253	  const plan = opts.noScale ? { hpMult: 1, spdMult: 1, armorAdd: 0 } : wavePlan(Math.max(wave, 1));
254	  if (!opts.affixes && !opts.noScale) opts.affixes = rollAffixes(kind);
255	  const e = makeEnemy(kind, world, {
256	    hpMult: plan.hpMult, spdMult: plan.spdMult * (1 + waveSpd), armorAdd: (plan.armorAdd || 0) + waveArmor,
257	    ...opts, t: opts.t ?? t,
258	  });
259	  if (e.fly) e.group.position.set(10.5, 1, -9.5);
260	  else { const p = world.curve.getPointAt(Math.min(Math.max(t, 0), 1)); e.group.position.set(p.x, .12, p.z); }
261	  enemies.push(e);
262	  world.scene.add(e.group);
263	  return e;
264	}
265	function killEnemy(e) {
266	  const r = Math.floor(e.def.reward * rewardMult * mods.essence);
267	  essence += r; ui.essencePop(r); audio.play('coin');
268	  fx.burst(e.pos(), e.def.color, 12, 2.2, 1.4);
269	  fx.ring(e.pos(true), e.def.color, 1.1, .35);
270	  if (e.boss) { report('event', { event: 'boss_slain' }); ui.banner('巨 像 陨 落', `+${r}✦`, 2.2); }
271	  // 「裂」affix: death splits into two minis (never re-split)
272	  if (e.affixes && e.affixes.includes('split') && !e.mini && !e.boss) {
273	    const plan = wavePlan(Math.max(wave, 1));
274	    for (const off of [-.014, .014]) {
275	      const m = spawn('crawler', Math.max(0, Math.min(.99, e.t + off)), { noScale: true, hpMult: plan.hpMult * .35, spdMult: plan.spdMult * 1.15, affixes: [] });
276	      m.mini = true;
277	      m.group.scale.setScalar(.68);
278	    }
279	    fx.burst(e.pos(), 0xff8a8a, 8, 1.6, 1.2);
280	    if (!e.leaked) ui.toast('「裂」分裂！两只幼体钻出');
281	  }
282	  e.dispose(world.scene);
283	}
284	
285	// --- build / upgrade / sell ---
286	function buildOn(key) {
287	  if (selPad < 0 || mode === 'title' || mode === 'over' || mode === 'win') return false;
288	  const pad = world.pads[selPad];
289	  if (pad.tower) return false;
290	  const cost = TOWERS[key].cost;
291	  if (essence < cost) { ui.toast('星尘不足'); audio.play('disable'); return false; }
292	  essence -= cost;
293	  const t = makeTower(key, pad, mods, fx, glowT);
294	  pad.tower = t; towers.push(t);
295	  audio.play('place');
296	  fx.ring(pad.pos, TOWERS[key].color, 1.4, .4);
297	  deselect();
298	  return true;
299	}
300	function selectPad(i) {
301	  if (mode !== 'build' && mode !== 'combat' && mode !== 'draft') return;
302	  selPad = i; selTower = null;
303	  ui.towerPanel(null);
304	  world.pads.forEach(p => { if (p.tower) p.tower.showRange(false); });
305	  ui.cards(true, affordMap());
306	  audio.play('click');
307	}
308	function selectTower(pad, t) {
309	  selTower = t; selPad = world.pads.indexOf(pad);
310	  world.pads.forEach(p => { if (p.tower && p.tower !== t) p.tower.showRange(false); });
311	  t.showRange(true, fogWave);
312	  ui.towerPanel(t);
313	  ui.cards(false, {});
314	  audio.play('click');
315	}
316	function deselect() {
317	  selPad = -1; selTower = null;
318	  ui.towerPanel(null); ui.cards(false, {});
319	  world.pads.forEach(p => { if (p.tower) p.tower.showRange(false); });
320	}
321	function affordMap() {
322	  const m = {};
323	  for (const k of Object.keys(TOWERS)) m[k] = essence >= TOWERS[k].cost;
324	  return m;
325	}
326	function upgradeSel() {
327	  if (!selTower) return false;
328	  if (selTower.lv >= 2) { ui.toast('已满级 Lv3'); return false; }
329	  const cost = selTower.def.upg[selTower.lv];
330	  if (essence < cost) { ui.toast(`星尘不足（需 ${cost}✦）`); return false; }
331	  essence -= cost;
332	  selTower.upgrade(); audio.play('upgrade');
333	  fx.ring(selTower.pad.pos, selTower.def.color, 1.6, .4);
334	  ui.towerPanel(selTower);
335	  return true;
336	}
337	function sellSel() {
338	  if (!selTower) return false;
339	  const v = sellValue(selTower);
340	  essence += v; ui.essencePop(v); audio.play('sell');
341	  selTower.pad.tower = null;
342	  selTower.dispose(world.scene);
343	  towers = towers.filter(t => t !== selTower);
344	  deselect();
345	  return true;
346	}
347	function toggleSpeed() { if (mode === 'build' || mode === 'combat') { speed = speed === 1 ? 2 : 1; ui.speed(speed); audio.play('click'); } }
348	function togglePause() {
349	  if (mode !== 'build' && mode !== 'combat' && mode !== 'draft') return;
350	  paused = !paused; ui.pause(paused);
351	}
352	
353	// --- combat hooks ---
354	const hooks = {
355	  onLeak(e) {
356	    coreHp -= e.def.coreDmg;
357	    world.setCoreFrac(Math.max(0, coreHp / CORE_MAX));
358	    ui.flash(); audio.play('leak');
359	    fx.ring(new THREE.Vector3(-5.5, .6, 0), 0xe05252, 2.2, .5);
360	    fx.burst(new THREE.Vector3(-5.5, 1.2, 0), 0xe05252, 18, 2.4, 1.6);
361	    ui.toast(`星核受损 -${e.def.coreDmg}`);
362	    if (coreHp <= 0) { coreHp = 0; loseGame(); }
363	  },
364	  onDeath(e) { killEnemy(e); },
365	  onHeal(sh) { fx.ring(sh.pos(), 0x9a5af0, 1.6, .4); audio.play('heal'); },
366	  onStomp(boss) {
367	    audio.play('stomp');
368	    fx.ring(boss.pos(true), 0xc05a45, 3.2, .55);
369	    let bestT = null, bd = 1e9;
370	    for (const t of towers) { const d = t.group.position.distanceTo(boss.pos(true)); if (d < bd) { bd = d; bestT = t; } }
371	    if (bestT) {
372	      bestT.disabledT = 3.5; bestT.setDisabled(true); bestT.fx.beamEnd(bestT._beamId);
373	      fx.burst(bestT.group.position.clone().add(new THREE.Vector3(0, 1, 0)), 0xc05a45, 10, 1.4, 1);
374	      audio.play('disable');
375	      if (selTower === bestT) ui.towerPanel(bestT);
376	      ui.toast('★ 践踏！' + bestT.def.zh + ' 停机 3.5s');
377	    }
378	  },
