    const t = towers[0] || G.place(0, 'ballista');
    const r0 = t.effRange(false);
    G.forceEvent('fog');
    const r1 = t.effRange(true);
    G.revertEvent('fog');
    ok('T21', r1 < r0 * .81 && t.effRange(false) === r0, `${r0.toFixed(2)}→${r1.toFixed(2)}`);
