1	// Frostpuck Arena 霜锋冰球 — a 2D Canvas air-hockey arena.
2	// guizang-game-skill series #5 (灯匠夜游 · 第 5 铺).
3	// Vanilla ES modules, procedural art, synthesized WebAudio, fixed-step loop,
4	// site report bridge, G debug hooks and the ?autotest=1 suite.
5	
6	import {
7	  W, H, TABLE, MID_Y, GOAL_L, GOAL_R, PUCK_R, PAD_R,
8	  clamp, finite, stepPuck, clampPaddle, reflectX,
9	} from './physics.js';
10	import { makeAudio } from './audio.js';
11	
12	// ==================== constants ====================
13	const DT = 1 / 60;
14	const GOAL_SCORE = 7;
15	const PLAYER_SPEED = 660;
16	const PLAYER_TRACK = 1900;
17	const COUNTDOWN_START = 2.6;
18	const COUNTDOWN_GOAL = 1.8;
19	const GOAL_HOLD = 1.55;
20	const BEST_KEY = 'fpa.best';
21	const MUTE_KEY = 'fpa.mute';
22	const AUTOTEST = new URLSearchParams(location.search).has('autotest');
23	const URLP = new URLSearchParams(location.search);
24	
25	const AI_PROFILES = {
26	  easy:   { key: 'easy',   label: '易', speed: 250, reaction: 0.34, predict: 0.12, error: 62, guard: 108, attack: 0.55 },
27	  medium: { key: 'medium', label: '中', speed: 402, reaction: 0.17, predict: 0.56, error: 24, guard: 100, attack: 0.8 },
28	  hard:   { key: 'hard',   label: '难', speed: 620, reaction: 0.055, predict: 0.94, error: 6, guard: 92, attack: 1 },
29	};
30	const DIFF_ORDER = ['easy', 'medium', 'hard'];
31	
32	function diffKey(v) {
33	  if (typeof v === 'number' || /^[1-3]$/.test(String(v))) {
34	    const i = clamp((parseInt(v, 10) || 2) - 1, 0, 2);
35	    return DIFF_ORDER[i];
36	  }
37	  return AI_PROFILES[v] ? v : 'medium';
38	}
39	
40	// ==================== persistent state ====================
41	let best = 0;
42	try { best = parseFloat(localStorage.getItem(BEST_KEY) || '0') || 0; } catch (e) { best = 0; }
43	let muted = false;
44	try { muted = localStorage.getItem(MUTE_KEY) === '1'; } catch (e) { muted = false; }
45	
46	const audio = makeAudio();
47	audio.setMuted(muted);
48	
49	// ==================== mutable game state ====================
50	let mode = 'title';                 // title | play | over
51	let gameMode = 'ai';                // ai | local
52	let aiDiff = 'medium';
53	let profile = AI_PROFILES.medium;
54	let phase = 'faceoff';              // faceoff | live | goal | over
55	let paused = false, noAuto = false;
56	let playerScore = 0, aiScore = 0;
57	let matchTime = 0, countdown = 0, goalT = 0;
58	let winner = null, lastScorer = null, lastCountInt = 0;
59	let nanFlag = false;
60	let animT = 0, rallyBannerT = 0;
61	let hitstopT = 0, shakeT = 0, shakeDur = 0, shakeAmp = 0, flashT = 0, goalPulseT = 0;
62	let aiTimer = 0, aiTx = W / 2, aiTy = TABLE.y + 100, aiSeed = 1.7;
63	let pointerDown = false;
64	
65	const puck = { x: W / 2, y: MID_Y, vx: 0, vy: 0, r: PUCK_R, rot: 0 };
66	const p1 = { x: W / 2, y: TABLE.y + TABLE.h - 82, vx: 0, vy: 0, tx: W / 2, ty: TABLE.y + TABLE.h - 82, r: PAD_R };
67	const p2 = { x: W / 2, y: TABLE.y + 82, vx: 0, vy: 0, tx: W / 2, ty: TABLE.y + 82, r: PAD_R };
68	
