106	function mulberry32(a) {
107	  return function () {
108	    a |= 0; a = (a + 0x6D2B79F5) | 0;
109	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
110	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
111	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
112	  };
113	}
114	function rr(c, x, y, w, h, r) {
115	  const q = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
116	  c.beginPath();
117	  c.moveTo(x + q, y);
118	  c.lineTo(x + w - q, y); c.quadraticCurveTo(x + w, y, x + w, y + q);
119	  c.lineTo(x + w, y + h - q); c.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
120	  c.lineTo(x + q, y + h); c.quadraticCurveTo(x, y + h, x, y + h - q);
121	  c.lineTo(x, y + q); c.quadraticCurveTo(x, y, x + q, y);
122	  c.closePath();
123	}
