305	function toWireReport(frame) {
306	  const score = Number.isFinite(frame.score) ? Math.round(frame.score) : undefined;
307	  if (frame.kind === 'progress') return { kind: 'progress', data: { ...frame } };
308	  if (frame.kind === 'event') return { kind: 'event', event: String(frame.event || frame.tag || 'event'), data: { ...frame } };
309	  if (frame.kind === 'gameOver') return { kind: 'gameOver', score, progress: (frame.progress && typeof frame.progress === 'object') ? frame.progress : { value: frame.progress }, data: { ...frame } };
310	  if (frame.kind === 'complete') return { kind: 'complete', score };
311	  return frame;
312	}
313	function report(kind, payload = {}) {
314	  const frame = { kind, ...payload };
315	  reports.push(frame);
316	  try {
317	    if (reportTarget) reportTarget(frame);
318	    else if (window.parent !== window) {
319	      window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: toWireReport(frame) }, '*');
320	      if (frame.kind === 'ready') window.parent.postMessage({ source: 'lightgame', type: 'lightgame:ready', gameId: 'frostpuck-arena', v: 1 }, '*');
321	    }
322	  } catch (e) { }
323	}
