function startMatch(gm = 'ai', diff = aiDiff) {
  gameMode = gm === 'local' ? 'local' : 'ai';
  aiDiff = diffKey(diff);
  profile = AI_PROFILES[aiDiff];
  mode = 'play'; paused = false; winner = null;
