  }),
  startMatch,
  startRound: (i) => { if (mode !== 'play') { mode = 'play'; hideOverlays(); } startRound(clamp(parseInt(i, 10) || 0, 0, 8)); return G_API.state(); },
  setPhase: (p) => {
    if (p === 'live') return beginLive();
    if (p === 'intro') { phase = 'intro'; return true; }
