function advanceRound() {
  if (phase !== 'result') return false;
  if (!round.overtime && roundIndex < 2) {
    startRound(roundIndex + 1);
    return true;
  }
  if (!round.overtime && roundIndex >= 2) {
    if (p1Wins === p2Wins) {
      overtime = true;
      startRound(3);
    } else {
      endMatch();
    }
    return true;
  }
  if (round.overtime) {
    if (p1Wins === p2Wins) startRound(roundIndex + 1);
    else endMatch();
    return true;
  }
  return false;
}

function saveBest() {
