    changed = true;
  }
  if (p1Wins > p2Wins && matchTime > 0 && (bestTime <= 0 || matchTime < bestTime)) {
    bestTime = Math.round(matchTime * 100) / 100;
    try { localStorage.setItem(BEST_TIME_KEY, String(bestTime)); } catch (e) { }
